import sys
t = int(input())
while t:
	(n, m) = map(int, input().split())
	h = n
	p = m
	n = min(h, p)
	m = max(h, p)
	b = [int(x) for x in input().split()]
	b.sort()
	x = min(n, m) - 1
	ch = (x + 1) // 2
	che = x // 2
	ans = sys.maxsize
	pos = -1
	for i in range(ch, n * m - che - n - m + 2):
		j = i + n + m - 2
		if ans > b[j] - b[i]:
			ans = b[j] - b[i]
			pos = i
	mat = [[0 for _ in range(m)] for _ in range(n)]
	if n <= m:
		k = pos
		l = 0
		for i in range(n):
			mat[i][0] = b[k]
			k += 1
		for i in range(1, m):
			mat[n - 1][i] = b[k]
			k += 1
		for i in range(0, n - 1, 2):
			mat[i][1] = b[l]
			l += 1
		for i in range(1, n - 1, 2):
			mat[i][1] = b[k]
			k += 1
		for i in range(0, n - 1):
			for j in range(2, m):
				if l < pos:
					mat[i][j] = b[l]
					l += 1
				else:
					mat[i][j] = b[k]
					k += 1
	else:
		mat = [[0 for _ in range(n)] for _ in range(m)]
		k = pos
		l = 0
		for i in range(m):
			mat[i][0] = b[k]
			k += 1
		for i in range(1, n):
			mat[m - 1][i] = b[k]
			k += 1
		for i in range(0, m - 1, 2):
			mat[i][1] = b[l]
			l += 1
		for i in range(1, m - 1, 2):
			mat[i][1] = b[k]
			k += 1
		for i in range(0, m - 1):
			for j in range(2, n):
				if l < pos:
					mat[i][j] = b[l]
					l += 1
				else:
					mat[i][j] = b[k]
					k += 1
	if h <= p:
		for i in range(n):
			for j in range(m):
				print(mat[i][j], end=' ')
			print()
	else:
		for i in range(m):
			for j in range(n):
				print(mat[j][i], end=' ')
			print()
	t -= 1
